"""Expand ALL existing course learning notes to 5000+ characters; idempotent; never changes users/bookings."""
from app import SessionLocal, Item
from seed_lessons_topics import TOPICS

TOPIC_MAP = {topic[0].lower():topic for topic in TOPICS}

def subject_data(title):
    label=title.replace(' — Free Learning Notes','').strip()
    for name,category,concepts,project,safety,reference in TOPICS:
        if name.lower()==label.lower() or name.lower() in label.lower():
            return name,category,concepts,project,safety,reference
    return label,'General skills','definitions, examples, common mistakes, decision-making and application',f'create a 1-page illustrated beginner guide on {label}', 'Check the reliability of sources and follow relevant safety guidance', 'NCERT textbooks, recognized universities and official learning materials'

def expanded(name,cat,concepts,project,safety,reference):
    terms=[x.strip() for x in concepts.replace(' and ',', ').split(',') if x.strip()]
    headings='; '.join(terms)
    parts=[
    f'''CHAPTER 1 — INTRODUCTION TO {name.upper()}\n\nWelcome to CareerSathi's beginner learning track. The subject is {name}. This is a self-study theory course, not a paid credential or live class. You do not need to finish everything in one sitting. Study a section, write your own notes, test one example, and return to the topic the next day. In this subject, you will encounter: {headings}. Each idea has a definition, a purpose and an application; learning means being able to explain all three without memorising isolated lines.\n\nStart a learning journal with today's date. Write what you currently think this subject involves. Identify one question you hope to answer, one career connected to it and one everyday situation where it might be useful. You will revisit these initial assumptions at the end of the lesson. If you cannot explain a word simply, mark it for review. A good student does not pretend to understand everything on the first attempt.\n\nA practical learning routine is to read carefully for 20 minutes, spend 20 minutes making your own example, and use the final 10 minutes to explain what you learned without looking at your notes. Breaks and consistent revision are more effective than rushing through a long page.''',
    f'''CHAPTER 2 — FIRST PRINCIPLES AND ESSENTIAL VOCABULARY\n\nCore ideas: {headings}. Treat each of these as a building block rather than as a list to memorise. A useful definition states what a concept is, identifies how it differs from nearby concepts and gives an example of where someone uses it. When you see a technical expression, ask: What information goes in? What changes? What result comes out? What assumptions were made? Which part could go wrong?\n\nBuild a four-column notebook table labelled Term, My definition, Example, and Questions. For the first term, describe it in plain language as though speaking to a Class 9 student. In the next column invent an example from home, school, a college or a local business. Repeat for every term. Compare your definitions with a reliable textbook or official tutorial and correct inaccuracies in a different colour so your progress remains visible.\n\nFoundations are connected. Understanding the first term helps you reason about the second; when you get stuck with a more advanced idea, return to the simplest example and change one part at a time. The goal is not to sound technical. The goal is to explain cause and effect, trade-offs and useful results clearly. If your subject involves numbers, show each calculation and its units. If it involves communication, explain the audience and purpose. If it involves code, explain inputs and outputs. If it involves a career choice, explain eligibility and alternatives.''',
    f'''CHAPTER 3 — A GUIDED PRACTICAL EXAMPLE\n\nYour guided assignment is: {project}. First write the problem in one sentence. Next describe the intended user or audience: a classmate, parent, teacher, career seeker or school coordinator. Define success in a way you can actually check. For example, someone else should be able to follow your explanation and understand the result without needing you to stand beside them.\n\nStep A — Plan. List at least five small actions in order. Identify the resources available to you, the missing information and the simplest first version you can finish. Do not begin by buying expensive equipment or software. Seek free and accessible tools and verify their terms.\n\nStep B — Draft. Produce a first version using a notebook, spreadsheet, presentation, safe simulation or basic project, depending on the topic. Keep evidence of how you worked: screenshots of non-sensitive project output, handwritten sketches or test results. Do not copy an entire answer without understanding it.\n\nStep C — Test. Create three realistic test cases: a typical situation, an unusual or incomplete situation and a situation where someone makes a mistake. Record the expected outcome before observing the actual outcome. When results disagree, identify whether the issue was the input, your assumption, your method or your interpretation.\n\nStep D — Improve. Ask one trusted person to try the result and explain their confusion. Change one feature to improve clarity. Write a short paragraph contrasting your first and final versions. This process matters because careers require learning, feedback and careful revision, not perfect first attempts.''',
    f'''CHAPTER 4 — HOW TO REASON THROUGH PROBLEMS\n\nImagine two students preparing for {name}. Student A copies ten definitions without seeing examples. Student B reads fewer definitions but explains every term, tests a small example and asks how the idea behaves when conditions change. Student B builds a more transferable skill. You should combine accurate reading with active practice.\n\nUse a five-question analysis method. (1) What exactly is being asked? (2) Which facts are given and which are assumptions? (3) Which of the core concepts — {headings} — are relevant? (4) What possible approach is simplest and safest? (5) How would you know that the answer is correct? If you cannot verify the final step, identify a trustworthy source, teacher or professional who can help.\n\nWhen two sources disagree, check their publication dates, author expertise, evidence and whether they are discussing the same circumstances. In career guidance, admission eligibility, examination schedules, fees and policies change. A social-media clip or student testimonial can be helpful context, but is not a substitute for official admission documents. Never interpret a general lesson as a personalised admission promise or professional opinion.\n\nReflection activity: write down a mistake you made while learning this subject. Explain what led to it, the evidence that helped you correct it and how you would avoid it next time. This is often more valuable than displaying only the final correct answer.''',
    f'''CHAPTER 5 — CLASSROOM AND CAREER CONNECTIONS\n\nHow can {name} connect to real life? It might improve a school assignment, support a community activity, help you understand a future degree or teach you to ask better questions before choosing a profession. Do not assume that learning one subject guarantees a job. Careers usually depend on a combination of foundational education, practical work, communication, ethical decision-making, opportunities and continuing practice.\n\nCreate a small career map with four boxes: What people in this field study; What they do in a normal week; Which strengths and working conditions suit the field; and What legitimate training or eligibility is required. For each box, write three questions to ask a mentor. Examples include: What surprised you about your course? What kind of assignments did you complete? How much independent practice was involved? What would you have chosen differently? What should a beginner try before making a decision?\n\nA mentor can describe personal experience, but their individual path is not universal. Verify institutional claims with the institution. Compare multiple pathways, not only the most famous college or career. Consider cost, distance, language, accessibility, scholarships, interests and the possibility of changing direction later. A strong choice is informed, realistic and flexible.\n\nMake a personal learning plan for four weeks: Week 1 understanding vocabulary; Week 2 working through examples; Week 3 improving the guided project; Week 4 sharing results and reflecting on next steps. Record progress rather than aiming for an unrealistic number of hours.''',
    f'''CHAPTER 6 — PRACTICE QUESTIONS AND SELF-CHECK\n\nExercise 1: Explain {name} in 100 to 150 words using vocabulary that a younger student could understand. Avoid unexplained jargon.\n\nExercise 2: Take these topic areas — {headings} — and create one original example for each. For every example, include an expected result or a reason for its usefulness.\n\nExercise 3: Complete the guided project: {project}. Write a short plan before you start, show intermediate work and state at least one limitation of your result.\n\nExercise 4: Describe two possible errors a beginner might make and how to detect each one. If the topic deals with real people, data or advice, mention how you would protect their safety and privacy.\n\nExercise 5: Create five quiz questions for a friend. Include a definition question, one application question, one comparison question, one 'what if' question and one question about verifying evidence. Write an answer key and revise any vague questions.\n\nExercise 6: Make a small concept map linking the major ideas from Chapter 2. Add arrows labelled with relationships such as 'depends on', 'influences', 'is an example of' or 'is checked by'.\n\nExercise 7: Keep a seven-day reflection log. On day one attempt the exercises with notes. On day three try explaining the topic without notes. On day seven identify what you still misunderstand and plan a targeted review. Improvement is the aim, not a perfect score.''',
    f'''CHAPTER 7 — ETHICS, ACCURACY AND NEXT STEPS\n\nImportant topic guidance: {safety}. Respect other people's information, avoid misleading claims and do not use an unfamiliar procedure in a high-risk setting without qualified supervision. When sharing examples, remove personal identifiers, passwords and sensitive records. Cite external material in your school projects and never claim someone else's work as your own.\n\nTo go beyond these introductory notes, consult: {reference}. Prefer current primary materials, recognised educators and official institutions. If you are researching Indian colleges, verify programme approval, admission routes and costs on their current websites. If you are comparing entrance examinations, check the conducting body's latest instructions rather than relying on older cutoffs.\n\nYour final activity is a 1-page learning portfolio: state your objective, define five core terms, present your project, discuss one error and its correction, and write two questions for a mentor. A short, genuine portfolio proves more about your growth than a decorative certificate without learning.\n\nCareerSathi is here to support exploration, not make binding educational decisions on your behalf. Want a plan for your school class or chosen stream? Create a free account, complete your assessment and tell a mentor what topics you have already studied. You can also use the contact form to request guidance. These notes are educational information and do not guarantee admission, employment or a formal qualification.'''
    ]
    text='\n\n'.join(parts)
    assert len(text)>=5000, (name,len(text))
    return text

with SessionLocal() as db:
    courses=db.query(Item).filter(Item.kind=='course').all()
    updated=0
    for item in courses:
        if len(item.description or '')>=5000:continue
        title,cat,concepts,project,safety,ref=subject_data(item.title)
        new=expanded(title,cat,concepts,project,safety,ref)
        item.description=(item.description.strip()+'\n\n' if item.description else '')+new
        if not item.subtitle: item.subtitle='Free theory, worked activities and practice questions'
        updated+=1
    db.commit()
    print(f'Expanded {updated} course(s). Total courses: {len(courses)}. Each now has at least 5000 characters. No users, bookings, mentors or admin accounts changed.')
